package org.sleepwell.app;
import android.app.*;import android.content.SharedPreferences;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
/** Original guided wind-down: reading and optional visual cue, no narration/audio/sensors/services. */
public final class GuidedWindDownActivity extends Activity {
 private final Handler handler=new Handler(Looper.getMainLooper());private GuidedWindDown guide;private SharedPreferences prefs;private boolean resumed;private Dialog picker;private TextView time,stepTitle,instruction,cue,status;private Button primary,end;private View durationRow;private Switch paced;private GuideCircle circle;private String notice="";private int shownStep=-1;private String shownCue="";
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);prefs=getSharedPreferences("guided_wind_down_v1",MODE_PRIVATE);int minutes=5;boolean visual=false;try{minutes=prefs.getInt("minutes",5);visual=prefs.getBoolean("paced",false);}catch(RuntimeException unreadable){notice="Last selection unavailable. Defaults are shown.";}if(saved!=null){minutes=saved.getInt("minutes",minutes);visual=saved.getBoolean("paced",visual);}if(minutes!=2&&minutes!=5&&minutes!=10)minutes=5;guide=new GuidedWindDown(minutes,visual);if(saved!=null){guide.restore(saved.getLong("elapsed"),saved.getString("state","READY"));if(guide.state==GuidedWindDown.State.PAUSED)notice="Paused after the screen changed. Resume when ready.";}render();}
 private void render(){shownStep=-1;shownCue="";LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Guided wind-down",this::finish);Design.space(body,10);Design.text(body,"Original silent reading practice · changing duration starts a new practice",14,500,Design.MUTED);Design.space(body,12);durationRow=Design.item(body,"clock","Practice duration",guide.minutes+" min",this::duration);paced=Design.toggle(body,"Optional paced visual cue","4 seconds in · 6 seconds out · no holds",guide.paced,on->{guide.paced=on;saveSelection();update();});Design.space(body,12);circle=new GuideCircle();body.addView(circle,new LinearLayout.LayoutParams(-1,Design.dp(this,180)));cue=Design.text(body,"",19,600,Design.INK);cue.setGravity(Gravity.CENTER);cue.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);time=Design.text(body,"",14,500,Design.MUTED);time.setGravity(Gravity.CENTER);Design.space(body,18);stepTitle=Design.text(body,"",23,600,Design.INK);stepTitle.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);Design.space(body,8);instruction=Design.text(body,"",16,400,Design.INK);Design.space(body,16);Design.text(body,"Breathe normally if a cue is not comfortable. You can pause or end at any time. This is a reading/visual guide, not recorded voice or a sleep, health or treatment measurement.",12,400,Design.MUTED);Design.space(body,8);Design.text(body,"Leaving this screen, locking the phone or switching apps pauses the practice. No sound, microphone, vibration or network is used by this guide.",12,400,Design.MUTED);status=Design.text(body,"",13,500,Design.BROWN);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);LinearLayout footer=RecordUi.footer(body);primary=Design.button(footer,"Start guide",true,this::toggle);end=Design.button(footer,"End practice",false,this::end);update();}
 private void duration(){if(guide.state==GuidedWindDown.State.RUNNING||picker!=null&&picker.isShowing())return;int[] values={2,5,10};picker=SleepPicker.choices(this,"Practice duration",new String[]{"2 minutes","5 minutes","10 minutes"},guide.minutes==2?0:guide.minutes==5?1:2,n->{guide=new GuidedWindDown(values[n],guide.paced);notice="";saveSelection();render();});}
 private void saveSelection(){try{prefs.edit().putInt("minutes",guide.minutes).putBoolean("paced",guide.paced).apply();}catch(RuntimeException unavailable){notice="Last selection could not be saved. The current guide remains available.";}}
 private void toggle(){if(!resumed||!hasWindowFocus())return;long now=SystemClock.elapsedRealtime();if(guide.state==GuidedWindDown.State.RUNNING){guide.pause(now);notice="Paused. The practice clock is stopped.";}else if(guide.state==GuidedWindDown.State.PAUSED){guide.resume(now);notice="";}else{saveSelection();guide.start(now);notice="";}update();}
 private void end(){if(!resumed||!hasWindowFocus())return;guide.end(SystemClock.elapsedRealtime());notice="Ended by you. No completion is assumed.";update();}
 private void update(){if(time==null)return;long now=SystemClock.elapsedRealtime();guide.tick(now);long elapsed=guide.elapsed(now),remaining=guide.total()-elapsed;time.setText(String.format(Locale.getDefault(),"%d:%02d remaining · %d min practice",(remaining+999)/60000,((remaining+999)/1000)%60,guide.minutes));int step=guide.step(now);if(shownStep!=step){shownStep=step;stepTitle.setText((step+1)+" / 5 · "+GuidedWindDown.TITLES[step]);instruction.setText(GuidedWindDown.WORDS[step]);}String phase=guide.state==GuidedWindDown.State.COMPLETED?"Practice complete":guide.state==GuidedWindDown.State.ENDED?"Practice ended":guide.state==GuidedWindDown.State.PAUSED?"Paused":guide.state==GuidedWindDown.State.READY?"Ready when you are":!guide.paced?"At your own pace":elapsed%10000<4000?"Breathe in, if comfortable":"Breathe out, if comfortable";if(!phase.equals(shownCue)){shownCue=phase;cue.setText(phase);}primary.setText(guide.state==GuidedWindDown.State.RUNNING?"Pause guide":guide.state==GuidedWindDown.State.PAUSED?"Resume guide":guide.state==GuidedWindDown.State.COMPLETED||guide.state==GuidedWindDown.State.ENDED?"Start again":"Start guide");primary.setEnabled(resumed&&hasWindowFocus());end.setEnabled((guide.state==GuidedWindDown.State.RUNNING||guide.state==GuidedWindDown.State.PAUSED)&&resumed&&hasWindowFocus());RecordUi.enabled(durationRow,guide.state!=GuidedWindDown.State.RUNNING);paced.setEnabled(guide.state!=GuidedWindDown.State.RUNNING);String message=guide.state==GuidedWindDown.State.COMPLETED?"The selected practice time is complete. There is no required result.":notice;if(!status.getText().toString().equals(message))status.setText(message);status.setVisibility(message.isEmpty()?View.GONE:View.VISIBLE);circle.invalidate();handler.removeCallbacks(tick);if(resumed&&guide.state==GuidedWindDown.State.RUNNING)handler.postDelayed(tick,200);}
 private final Runnable tick=this::update;
 private void pauseForScreen(){if(guide==null)return;if(guide.state==GuidedWindDown.State.RUNNING){guide.pause(SystemClock.elapsedRealtime());notice="Paused when the guide left focus. Resume when ready.";}handler.removeCallbacks(tick);update();}
 @Override protected void onResume(){super.onResume();resumed=true;update();}
 @Override protected void onPause(){resumed=false;pauseForScreen();super.onPause();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(guide!=null){if(!focused)pauseForScreen();else{RecordUi.lightBars(this);update();}}}
 @Override public void onSaveInstanceState(Bundle out){pauseForScreen();super.onSaveInstanceState(out);out.putInt("minutes",guide.minutes);out.putBoolean("paced",guide.paced);out.putLong("elapsed",guide.elapsed(SystemClock.elapsedRealtime()));out.putString("state",guide.state.name());}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(picker!=null)picker.dismiss();super.onDestroy();}
 private final class GuideCircle extends View {private final Paint paint=new Paint(3);GuideCircle(){super(GuidedWindDownActivity.this);setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);}protected void onDraw(Canvas c){super.onDraw(c);float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(getWidth(),getHeight())*.40f;long elapsed=guide.elapsed(SystemClock.elapsedRealtime());double phase=elapsed%10000/1000d;float amount=(float)(phase<4?phase/4:1-(phase-4)/6);boolean moving=guide.paced&&guide.state==GuidedWindDown.State.RUNNING&&!Appearance.reduced(getContext());paint.setStyle(Paint.Style.FILL);paint.setColor(Design.SOFT);c.drawCircle(x,y,r,paint);paint.setColor(0xffe4d2fa);c.drawCircle(x,y,r*(moving?.42f+.38f*amount:.67f),paint);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(Design.dp(getContext(),5));paint.setStrokeCap(Paint.Cap.ROUND);paint.setColor(Design.VIOLET);c.drawArc(x-r,y-r,x+r,y+r,-90,360f*elapsed/guide.total(),false,paint);paint.setStyle(Paint.Style.FILL);}}
}
